<?php use yii\helpers\{Html,Url};$this->title='Dashboard';?><section class="hero"><div><p>REGIONAL PROPERTY OVERVIEW</p><h2>Good day, <?=Html::encode(explode(' ',Yii::$app->user->identity->name)[0])?>.</h2></div><?=Html::a('+ Register asset',['/module/assets','new'=>1],['class'=>'btn light'])?></section><section class="kpis"><article><span>Total Assets</span><strong><?=number_format($total)?></strong><small>master records</small></article><article><span>Acquisition Amount</span><strong>₱<?=number_format($amount/1000000,2)?>M</strong><small>total value</small></article><article><span>Book Value</span><strong>₱<?=number_format($book/1000000,2)?>M</strong><small>current records</small></article><article><span>Active Assets</span><strong><?=number_format($active)?></strong><small>in service</small></article><article class="risk" role="link" tabindex="0" onclick="location.href='<?=Url::to(['/site/dashboard','attention'=>1])?>#dashboard-results'" style="cursor:pointer"><span>Attention Needed</span><strong><?=$risk?></strong><small>flagged records · click to view</small></article></section><section class="charts"><article class="panel"><h3>Assets by office</h3><canvas id="office"></canvas></article><article class="panel"><h3>Asset status</h3><canvas id="status"></canvas></article></section><?php if($title):?><section class="panel tablepanel" id="dashboard-results"><div class="panelhead"><h3><?=count($rows)?> assets — <?=Html::encode($title)?></h3><?=Html::a('Clear selection',['dashboard'])?></div><div class="scroll"><table><thead><tr><th>Property No.</th><th>Article / Model</th><th>Office / Location</th><th>Officer</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=Html::encode($r->property_number)?></strong></td><td><?=Html::encode($r->article)?><span><?=Html::encode($r->brand_model)?></span></td><td><?=Html::encode($r->office)?><span><?=Html::encode($r->location)?></span></td><td><?=Html::encode($r->accountable_officer)?></td><td><em class="badge"><?=Html::encode($r->system_status)?></em></td></tr><?php endforeach?></tbody></table></div></section><?php endif?><script>const officeChart=new Chart(document.getElementById('office'),{type:'bar',data:{labels:<?=json_encode(array_column($offices,'office'))?>,datasets:[{data:<?=json_encode(array_map('intval',array_column($offices,'c')))?>,backgroundColor:'#2563eb',borderRadius:7}]},options:{onHover:(e,x)=>e.native.target.style.cursor=x.length?'pointer':'default',onClick:(e,x,c)=>{if(x.length)location.href='<?=Url::to(['/site/dashboard'])?>?office='+encodeURIComponent(c.data.labels[x[0].index])+'#dashboard-results'},plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});new Chart(document.getElementById('status'),{type:'doughnut',data:{labels:<?=json_encode(array_column($statuses,'system_status'))?>,datasets:[{data:<?=json_encode(array_map('intval',array_column($statuses,'c')))?>,backgroundColor:['#16a34a','#ef4444','#f59e0b','#64748b','#8b5cf6']}]},options:{cutout:'68%'}});</script>
